        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        def generator(rng):
    # Choose p in a small range to keep answers reasonable and nontrivial
    # p=2 recovers the seed case but the family allows p=3,4 which are significantly harder
    p = rng.choice([2, 3, 4])
    return {'p': p}

        import math

def _min_D_for_t(p, t):
    # D(a; t) = a^{-p} + t b^{-p} - (a^p + t b^p), where b = 1 - (a-1)/t, a in (1, 1+t)
    # Robust 1D minimization over a using grid sampling + golden section refinement
    def D(a):
        b = 1.0 - (a - 1.0)/t
        if b <= 0:
            return float('inf')
        return (a**(-p) + t * (b**(-p))) - (a**p + t * (b**p))

    a_low = 1.0 + 1e-10
    a_high = 1.0 + t - 1e-10
    if not (a_high > a_low):
        return float('inf')

    # coarse grid search
    N = 500
    best_a = None
    best_val = float('inf')
    for i in range(N):
        a = a_low + (a_high - a_low) * (i + 0.5) / N
        val = D(a)
        if val < best_val:
            best_val = val
            best_a = a

    # golden section search around best grid point
    phi = (1 + 5**0.5) / 2
    w = max((a_high - a_low) / N * 4.0, 1e-9)
    L = max(a_low, best_a - w)
    R = min(a_high, best_a + w)
    if R <= L:
        L, R = a_low, a_high

    # Golden section minimize
    c = R - (R - L) / phi
    d = L + (R - L) / phi
    fc = D(c)
    fd = D(d)
    for _ in range(120):
        if fc < fd:
            R, d, fd = d, c, fc
            c = R - (R - L) / phi
            fc = D(c)
        else:
            L, c, fc = c, d, fd
            d = L + (R - L) / phi
            fd = D(d)
    return min(fc, fd, best_val)


def verifier(assign):
    # Validate inputs
    if 'p' not in assign:
        # Missing parameter
        return (False, None)
    p = assign['p']
    if not isinstance(p, int) or p < 2:
        # Invalid exponent
        return (False, None)

    # Define the critical t search: the smallest t ≥ 1 for which there exists a two-level configuration
    # with 1 large and t small (others equal to 1) that violates the inequality.
    # The maximal n for which the inequality holds for all x_i is then n_max = t_crit - 1 + 1 = t_crit? No: we show below it equals t_crit.
    # Explanation: a counterexample supported on (t+1) non-1 entries extends to any n ≥ t+1 by padding with 1's; hence the
    # largest n that forces the inequality for all vectors is exactly t_crit.

    # We compute the minimal D over a for each t, and find the first t where it becomes negative.
    # If no such t up to a reasonable cap, raise the cap; if still none, declare invalid.

    t_cap = 240
    found_t = None
    for t in range(1, t_cap + 1):
        val = _min_D_for_t(p, t)
        if val < -1e-12:
            found_t = t
            break

    if found_t is None:
        # Increase cap as a fallback
        for t in range(t_cap + 1, t_cap * 2 + 1):
            val = _min_D_for_t(p, t)
            if val < -1e-12:
                found_t = t
                break

    if found_t is None:
        # Could not certify within bounds; extremely unlikely for p in {2,3,4}
        return (False, None)

    # The answer is the largest n such that inequality holds for all choices, which equals found_t - 1 + 1 = found_t
    # as detailed in the notes/proof: the first violating configuration uses exactly t+1 non-1 entries, giving failure starting at n = t+1,
    # hence the maximal universal n is t.
    answer = found_t
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

